CREATE DATABASE IF NOT EXISTS holy_spirit_institute CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE holy_spirit_institute;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs,message_recipients,messages,notifications,events,notices,fee_payments,fees,marks,results,exam_subjects,exams,study_materials,assignment_submissions,assignments,attendance,timetables,class_subjects,student_classes,student_parents,teacher_classes,teacher_subjects,subjects,divisions,classes,academic_years,students,teachers,parents,users,school_settings;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','teacher','student','parent') NOT NULL,full_name VARCHAR(160) NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(role)) ENGINE=InnoDB;
CREATE TABLE parents(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(190),phone VARCHAR(30),address TEXT,status ENUM('Active','Inactive') DEFAULT 'Active',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE teachers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,employee_id VARCHAR(50) UNIQUE,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(190),phone VARCHAR(30),qualification VARCHAR(190),joining_date DATE,address TEXT,photo VARCHAR(255),status ENUM('Active','Inactive') DEFAULT 'Active',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE classes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) UNIQUE NOT NULL,status ENUM('Active','Inactive') DEFAULT 'Active') ENGINE=InnoDB;
CREATE TABLE divisions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,class_id INT UNSIGNED NOT NULL,name VARCHAR(30) NOT NULL,class_teacher_id INT UNSIGNED NULL,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,FOREIGN KEY(class_teacher_id) REFERENCES teachers(id) ON DELETE SET NULL,UNIQUE(class_id,name)) ENGINE=InnoDB;
CREATE TABLE subjects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,code VARCHAR(30),status ENUM('Active','Inactive') DEFAULT 'Active') ENGINE=InnoDB;
CREATE TABLE academic_years(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) UNIQUE,start_date DATE,end_date DATE,is_current TINYINT(1) DEFAULT 0);
CREATE TABLE students(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,admission_number VARCHAR(50) UNIQUE NOT NULL,roll_number VARCHAR(30),first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80),date_of_birth DATE,gender ENUM('Male','Female','Other'),email VARCHAR(190),phone VARCHAR(30),address TEXT,class_id INT UNSIGNED,division_id INT UNSIGNED,parent_id INT UNSIGNED,admission_date DATE,photo VARCHAR(255),status ENUM('Active','Inactive','Transferred','Graduated') DEFAULT 'Active',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL,FOREIGN KEY(parent_id) REFERENCES parents(id) ON DELETE SET NULL,INDEX(class_id,division_id),INDEX(parent_id)) ENGINE=InnoDB;
CREATE TABLE teacher_subjects(teacher_id INT UNSIGNED,subject_id INT UNSIGNED,PRIMARY KEY(teacher_id,subject_id),FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE teacher_classes(teacher_id INT UNSIGNED,class_id INT UNSIGNED,PRIMARY KEY(teacher_id,class_id),FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE);
CREATE TABLE student_parents(student_id INT UNSIGNED,parent_id INT UNSIGNED,relationship_name VARCHAR(40),PRIMARY KEY(student_id,parent_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES parents(id) ON DELETE CASCADE);
CREATE TABLE student_classes(student_id INT UNSIGNED,class_id INT UNSIGNED,division_id INT UNSIGNED,academic_year_id INT UNSIGNED,PRIMARY KEY(student_id,academic_year_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL,FOREIGN KEY(academic_year_id) REFERENCES academic_years(id) ON DELETE CASCADE);
CREATE TABLE class_subjects(class_id INT UNSIGNED,subject_id INT UNSIGNED,PRIMARY KEY(class_id,subject_id),FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE timetables(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,class_id INT UNSIGNED NOT NULL,division_id INT UNSIGNED NOT NULL,day_name ENUM('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday') NOT NULL,period_no INT NOT NULL,start_time TIME,end_time TIME,subject_id INT UNSIGNED NOT NULL,teacher_id INT UNSIGNED NOT NULL,room VARCHAR(50),FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(teacher_id) REFERENCES teachers(id),INDEX(day_name,class_id,division_id),INDEX(teacher_id,day_name,period_no));
CREATE TABLE attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id INT UNSIGNED NOT NULL,class_id INT UNSIGNED NOT NULL,division_id INT UNSIGNED NOT NULL,subject_id INT UNSIGNED NULL,teacher_id INT UNSIGNED NULL,attendance_date DATE NOT NULL,status ENUM('Present','Absent','Late') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE SET NULL,UNIQUE(student_id,attendance_date,subject_id));
CREATE TABLE assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,class_id INT UNSIGNED NOT NULL,division_id INT UNSIGNED NULL,subject_id INT UNSIGNED NOT NULL,teacher_id INT UNSIGNED NOT NULL,assigned_date DATE NOT NULL,due_date DATE NOT NULL,attachment VARCHAR(255),FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(teacher_id) REFERENCES teachers(id),INDEX(class_id,division_id,due_date));
CREATE TABLE assignment_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,assignment_id BIGINT UNSIGNED NOT NULL,student_id INT UNSIGNED NOT NULL,submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,attachment VARCHAR(255),remarks TEXT,status ENUM('Submitted','Pending','Late') DEFAULT 'Submitted',UNIQUE(assignment_id,student_id),FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE study_materials(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,class_id INT UNSIGNED,subject_id INT UNSIGNED,chapter VARCHAR(120),teacher_id INT UNSIGNED,material_type ENUM('PDF','Notes','Worksheet','Document','Image','Video') NOT NULL,file_path VARCHAR(255),external_url VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE SET NULL);
CREATE TABLE exams(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_name VARCHAR(150) NOT NULL,class_id INT UNSIGNED NOT NULL,division_id INT UNSIGNED NULL,exam_date DATE,start_time TIME,end_time TIME,FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL);
CREATE TABLE exam_subjects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_id INT UNSIGNED NOT NULL,subject_id INT UNSIGNED NOT NULL,maximum_marks DECIMAL(8,2) NOT NULL,passing_marks DECIMAL(8,2) NOT NULL,FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE,UNIQUE(exam_id,subject_id));
CREATE TABLE marks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_subject_id INT UNSIGNED NOT NULL,student_id INT UNSIGNED NOT NULL,obtained_marks DECIMAL(8,2) NOT NULL,FOREIGN KEY(exam_subject_id) REFERENCES exam_subjects(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,UNIQUE(exam_subject_id,student_id));
CREATE TABLE results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id INT UNSIGNED NOT NULL,exam_id INT UNSIGNED NOT NULL,total_marks DECIMAL(10,2),obtained_marks DECIMAL(10,2),percentage DECIMAL(6,2),grade VARCHAR(10),result_status VARCHAR(20),published TINYINT(1) DEFAULT 0,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,UNIQUE(student_id,exam_id));
CREATE TABLE fees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id INT UNSIGNED NOT NULL,fee_type VARCHAR(100) NOT NULL,total_amount DECIMAL(12,2) NOT NULL,paid_amount DECIMAL(12,2) DEFAULT 0,due_date DATE,status ENUM('Pending','Partial','Paid') DEFAULT 'Pending',FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE fee_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fee_id BIGINT UNSIGNED NOT NULL,receipt_number VARCHAR(80) UNIQUE NOT NULL,payment_date DATE NOT NULL,amount DECIMAL(12,2) NOT NULL,payment_method ENUM('Cash','UPI','Bank Transfer','Cheque','Other') NOT NULL,status ENUM('Success','Cancelled') DEFAULT 'Success',FOREIGN KEY(fee_id) REFERENCES fees(id) ON DELETE CASCADE);
CREATE TABLE notices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,target ENUM('Everyone','Teachers','Students','Parents','Specific Class','Specific Division') NOT NULL,publish_date DATE NOT NULL,expiry_date DATE,attachment VARCHAR(255),created_by INT UNSIGNED,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,event_type ENUM('School Event','Exam','Parent Meeting','Holiday','Activity') NOT NULL,event_date DATE NOT NULL,start_time TIME,end_time TIME,description TEXT);
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,message TEXT NOT NULL,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_id INT UNSIGNED NOT NULL,subject VARCHAR(200),body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE message_recipients(message_id BIGINT UNSIGNED,recipient_id INT UNSIGNED,is_read TINYINT(1) DEFAULT 0,PRIMARY KEY(message_id,recipient_id),FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE,FOREIGN KEY(recipient_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE school_settings(setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL);
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,action VARCHAR(100) NOT NULL,description TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);

